package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;

/** Ordered peer-group evidence, always requalified through ordinary approval authority. */
final class GroupApprovals {
 private GroupApprovals() {}
 static List<?> groups(Map<String,Object> definition,String target){return (List<?>)object(object(definition.getOrDefault("transition_rules",map())).getOrDefault(target,map())).getOrDefault("approval_groups",List.of());}
 static void validate(Object input){require(input instanceof List<?>,"Approval groups must be a list");var groups=(List<?>)input;require(!groups.isEmpty() && groups.size()<=5,"Provide 1 to 5 ordered groups");require(new HashSet<>(groups).size()==groups.size(),"Approval groups must be distinct");for(var group:groups)require(group instanceof String && ((String)group).matches("[0-9a-f]{32}"),"Use existing group IDs");}
 static boolean member(Store.Db db,String group,String user)throws SQLException {return db.count("SELECT COUNT(*) FROM os_group_member m JOIN os_record g ON g.sys_id=m.group_id AND g.\"table\"='sys_user_group' JOIN os_user u ON u.user_id=m.user_id WHERE m.group_id=? AND m.user_id=? AND u.active=1 AND u.role IN ('admin','agent') AND u.password_reset_required=0",group,user)==1;}
 static String label(Store.Db db,String group)throws SQLException {try{return Objects.toString(FieldAccess.serialize(db,Service.readRecord(db,"sys_user_group",group)).get("short_description"),"Review team");}catch(Failure denied){return "Unavailable review team";}}
 static List<Map<String,Object>> progress(Store.Db db,Map<String,Object> item,Map<String,Object> definition,String target,List<String> qualified)throws SQLException {
  var groups=groups(definition,target);if(groups.isEmpty())return List.of();var rows=db.all("SELECT a.*,g.group_id,g.stage_index FROM os_approval a JOIN os_approval_group g ON g.approval_id=a.approval_id WHERE a.record_id=? AND a.record_revision=? AND a.schema_version=? AND a.target_state=? ORDER BY a.sequence",item.get("sys_id"),item.get("revision"),Approvals.version(definition),target);boolean rejected=rows.stream().anyMatch(row->row.get("status").equals("rejected"));var result=new ArrayList<Map<String,Object>>();long after=-1;boolean blocked=false;
  for(int stage=0;stage<groups.size();stage++){String group=groups.get(stage).toString(),chosen="";long sequence=after;if(!blocked && !rejected)for(var row:rows)if(((Number)row.get("stage_index")).intValue()==stage && row.get("group_id").equals(group) && ((Number)row.get("sequence")).longValue()>after && qualified.contains(row.get("approval_id")) && member(db,group,row.get("approver_id").toString())){chosen=row.get("approval_id").toString();sequence=((Number)row.get("sequence")).longValue();break;}String status=rejected?"rejected":blocked?"waiting":chosen.isEmpty()?"pending":"approved";result.add(map("index",stage,"group_id",group,"group_name",label(db,group),"status",status,"approval_id",chosen));blocked=blocked || chosen.isEmpty();after=sequence;}
  return result;
 }
 static int position(List<Map<String,Object>> stages){require(!stages.isEmpty(),"This transition has no group policy");for(var stage:stages){if(stage.get("status").equals("rejected"))throw new Failure(409,"This proposal was rejected; save a new record revision before requesting review");if(!stage.get("status").equals("approved"))return ((Number)stage.get("index")).intValue();}throw new Failure(409,"All group stages already have current approvals");}
 static void assign(Store.Db db,Map<String,Object> item,Map<String,Object> definition,String target,String reviewer,String approval)throws SQLException {
  var groups=groups(definition,target);if(groups.isEmpty())return;int stage=position(progress(db,item,definition,target,ApprovalGate.qualifying(db,item,definition,target)));String group=groups.get(stage).toString();require(member(db,group,reviewer),"Choose a current eligible member of the pending review team");db.update("INSERT INTO os_approval_group(approval_id,group_id,stage_index) VALUES(?,?,?)",approval,group,stage);
 }
 static void delegate(Store.Db db,String approval,String reviewer)throws SQLException {var proof=db.one("SELECT group_id FROM os_approval_group WHERE approval_id=?",approval);if(proof!=null)require(member(db,proof.get("group_id").toString(),reviewer),"Delegate within the current review team");}
 static void review(Store.Db db,Map<String,Object> item,Map<String,Object> definition,Map<String,Object> approval)throws SQLException {
  String target=approval.get("target_state").toString();if(groups(definition,target).isEmpty())return;var proof=db.one("SELECT group_id,stage_index FROM os_approval_group WHERE approval_id=?",approval.get("approval_id"));require(proof!=null,"A group-policy review must retain its stage evidence");require(member(db,proof.get("group_id").toString(),approval.get("approver_id").toString()),"Current review-team membership is required");var stages=progress(db,item,definition,target,ApprovalGate.qualifying(db,item,definition,target));int stage=position(stages);require(((Number)proof.get("stage_index")).intValue()==stage,"Earlier group stages must remain qualified before this decision");for(int n=0;n<stage;n++){long earlier=db.count("SELECT sequence FROM os_approval WHERE approval_id=?",stages.get(n).get("approval_id"));if(((Number)approval.get("sequence")).longValue()<=earlier)throw new Failure(409,"An earlier stage was replaced; withdraw this request and request the team again");}
 }
 static void complete(Store.Db db,Map<String,Object> item,Map<String,Object> approval,Map<String,Object> actor,String outcome)throws SQLException {
  var proof=db.one("SELECT stage_index FROM os_approval_group WHERE approval_id=?",approval.get("approval_id"));if(proof==null)return;String filter=outcome.equals("rejected")?"":" AND g.stage_index=?";var args=new ArrayList<Object>(List.of(approval.get("record_id"),approval.get("record_revision"),approval.get("schema_version"),approval.get("target_state")));if(!filter.isEmpty())args.add(proof.get("stage_index"));var pending=db.all("SELECT a.approval_id FROM os_approval a JOIN os_approval_group g ON g.approval_id=a.approval_id WHERE a.record_id=? AND a.record_revision=? AND a.schema_version=? AND a.target_state=? AND a.status='requested'"+filter,args.toArray());for(var row:pending)db.update("UPDATE os_approval SET status='withdrawn',comment=?,decided_at=?,decision_revision=? WHERE approval_id=?","Closed by group stage outcome: "+outcome,now(),actor.get("auth_revision"),row.get("approval_id"));Service.audit(db,item,actor.get("name").toString(),"approval.group_completed",map("approval_id",approval.get("approval_id"),"outcome",outcome,"closed_pending",pending.size()));
 }
 static Map<String,Object> request(Store.Db db,String table,String id,Map<String,Object> actor,Object input)throws SQLException {
  var body=object(input);require(body.keySet().equals(Set.of("expected_revision","target_state","reason")),"Provide expected_revision, target_state and reason");require(body.get("expected_revision") instanceof Integer,"Provide an integer record revision");String target=WorkJobs.text(body.get("target_state"),80),reason=Approvals.text(body.get("reason"),true);var item=Approvals.context(db,table,id);if(!item.get("revision").toString().equals(body.get("expected_revision").toString()))throw new Failure(409,"Record changed; reload before requesting a group stage");var definition=Service.schema(db,table);Approvals.eligible(db,table,item,definition,target);int stage=position(progress(db,item,definition,target,ApprovalGate.qualifying(db,item,definition,target)));String group=groups(definition,target).get(stage).toString();Service.readRecord(db,"sys_user_group",group);
  var candidates=db.all("SELECT u.* FROM os_group_member m JOIN os_user u ON u.user_id=m.user_id WHERE m.group_id=? AND u.active=1 AND u.password_reset_required=0 AND u.role IN ('admin','agent') AND u.user_id<>? AND NOT EXISTS(SELECT 1 FROM os_approval a WHERE a.record_id=? AND a.record_revision=? AND a.schema_version=? AND a.target_state=? AND a.approver_id=u.user_id AND a.status<>'withdrawn') ORDER BY u.user_id LIMIT 101",group,actor.get("user_id"),id,item.get("revision"),Approvals.version(definition),target);require(candidates.size()<=100,"At most 100 eligible team candidates can be requested at once");var eligible=new ArrayList<Map<String,Object>>();String original=db.viewerId,role=db.viewerRole;
  for(var user:candidates){try{db.viewerId=user.get("user_id").toString();db.viewerRole=user.get("role").toString();Service.readRecord(db,table,id);Approvals.eligible(db,table,item,definition,target);eligible.add(user);}catch(Failure denied){/* Current authority excludes this candidate. */}finally{db.viewerId=original;db.viewerRole=role;}}
  if(eligible.isEmpty())throw new Failure(409,"No new eligible reviewer is available for the current team");var approvals=new ArrayList<Object>();for(var user:eligible)approvals.add(Approvals.request(db,table,id,actor,map("expected_revision",body.get("expected_revision"),"approver",user.get("name"),"target_state",target,"reason",reason)).get("approval_id"));return map("stage",stage,"approval_ids",approvals,"requested",approvals.size());
 }
 static Map<String,Object> policy(Store.Db db,String table)throws SQLException {Service.requireAccountAdministrator(db,db.viewerId);var definition=Service.schema(db,table);require(object(definition.get("fields")).containsKey("state"),"Choose a stateful table");var policies=new ArrayList<Map<String,Object>>();for(var entry:object(definition.getOrDefault("transition_rules",map())).entrySet()){var names=new ArrayList<String>();for(var group:groups(definition,entry.getKey()))names.add(label(db,group.toString()));policies.add(map("label",object(definition.get("states")).get(entry.getKey()),"teams",names,"minimum",ApprovalGate.required(definition,entry.getKey())));}return map("table",table,"definition",definition,"version",Approvals.version(definition),"policies",policies,"groups",Service.page(db,"sys_user_group",Map.of("sysparm_limit","100"),"").rows());}
 static Map<String,Object> configure(Store.Db db,String table,Object input)throws SQLException {
  var page=policy(db,table);var body=object(input);require(body.keySet().equals(Set.of("version","target_state","groups")),"Provide version, target_state and ordered groups");var definition=new LinkedHashMap<>(object(page.get("definition")));require(body.get("version") instanceof Integer,"Provide an integer schema version");if(!body.get("version").equals(Approvals.version(definition)))throw new Failure(409,"Configuration changed; reload the policy");String target=WorkJobs.text(body.get("target_state"),80);require(object(definition.get("states")).containsKey(target),"Choose an existing target state");require(body.get("groups") instanceof List<?>,"Groups must be a list");var groups=(List<?>)body.get("groups");if(!groups.isEmpty())validate(groups);for(var group:groups)Service.readRecord(db,"sys_user_group",group.toString());var transitions=new LinkedHashMap<>(object(definition.getOrDefault("transition_rules",map())));var rule=new LinkedHashMap<>(object(transitions.getOrDefault(target,map())));rule.remove("min_approvals");if(groups.isEmpty())rule.remove("approval_groups");else rule.put("approval_groups",groups);transitions.put(target,rule);definition.put("transition_rules",transitions);definition.putIfAbsent("version",0);return Configuration.install(db,map("format",Configuration.FORMAT,"tables",map(table,definition)),db.viewerId,false);
 }
}
